(()=>{function draw(){if(tab!==0)return;const c=data.characters[ci];if(!c||c.specialReference)return;const card=document.querySelector('#contactSheetDisplay'),merge=document.querySelector('#mergeCharacterViews');if(!card&&!merge)return;const button=document.createElement('button');button.id='uploadMergedCharacterSheet';button.textContent=card?'上传替换合图':'上传人物合图';button.style.cssText='width:auto;margin:10px 0;padding:8px 14px';button.disabled=roleIsBusy(c);const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg,image/webp';input.hidden=true;button.onclick=()=>input.click();input.onchange=async()=>{const file=input.files[0];if(!file)return;const project=data.project_id;button.disabled=true;button.textContent='正在保存合图…';try{if(file.size>32*1024*1024)throw Error('图片不能超过32MB');await ensureProjectSaved();const bitmap=await createImageBitmap(file);if(bitmap.width>8192||bitmap.height>8192||bitmap.width*bitmap.height>32000000){bitmap.close();throw Error('图片最长边不能超过8192，总像素不能超过3200万');}const canvas=document.createElement('canvas');canvas.width=bitmap.width;canvas.height=bitmap.height;canvas.getContext('2d').drawImage(bitmap,0,0);bitmap.close();const png=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('读取图片失败')),'image/png'));const params=new URLSearchParams({project_id:project,character_id:String(c.id||c.character_id||c.name),layout:'row',sources:'[]'});const response=await fetch('/api/contact-sheet?'+params,{method:'POST',headers:{'Content-Type':'image/png'},body:png}),sheet=await response.json();if(!response.ok)throw Error(sheet.error||'上传失败');if(project!==data.project_id)throw Error('项目已切换，请回原项目重新选择');c.contactSheets??=[];c.contactSheets.push({...sheet,uploaded:true});c.contactSheetActive=c.contactSheets.length-1;c.useExternalReference=false;c.reference_images??={};c.reference_images.four_view=sheet.image_url;save();await ensureProjectSaved();render();toast('已替换人物合图，单张视图保持不变，旧合图保留历史版本');}catch(e){toast(e.message);button.disabled=false;button.textContent=card?'上传替换合图':'上传人物合图';}finally{input.value='';}};(card||merge.parentElement).append(button,input);}const previous=characters;characters=function(){previous();draw();};render();})();